47	    {
48	        if (userRegex.map(regex -> regex.matcher(user).matches()).orElse(true) &&
49	                catalogRegex.map(regex -> regex.matcher(catalog).matches()).orElse(true)) {
50	            return Optional.of(accessMode);
51	        }
52	        return Optional.empty();
53	    }
