55	    public enum AccessMode
56	    {
57	        ALL("all"),
58	        READ_ONLY("read-only"),
59	        NONE("none");
60	
61	        private static final Map<String, AccessMode> modeByName = Maps.uniqueIndex(ImmutableList.copyOf(AccessMode.values()), AccessMode::toString);
