26	public class PrincipalUserMatchRule
27	{
28	    private final Pattern principalRegex;
29	    private final Optional<Pattern> userRegex;
30	    private final Optional<String> principalToUserSubstitution;
31	    private final boolean allow;
32	
33	    @JsonCreator
34	    public PrincipalUserMatchRule(
35	            @JsonProperty("principal") Pattern principalRegex,
36	            @JsonProperty("user") Optional<Pattern> userRegex,
37	            @JsonProperty("principal_to_user") Optional<String> principalToUserSubstitution,
38	            @JsonProperty("allow") boolean allow)
39	    {
40	        this.principalRegex = requireNonNull(principalRegex, "principalRegex is null");
41	        this.userRegex = requireNonNull(userRegex, "userRegex is null");
42	        this.principalToUserSubstitution = requireNonNull(principalToUserSubstitution, "principalToUserSubstitution is null");
43	        checkState(
44	                userRegex.isPresent() || principalToUserSubstitution.isPresent(),
45	                "A valid principal rule must provide at least one criterion of user and user_extraction");
46	        this.allow = allow;
47	    }
48	
49	    public Optional<Boolean> match(String principal, String user)
50	    {
51	        Matcher matcher = principalRegex.matcher(principal);
52	
53	        if (!matcher.matches()) {
54	            return Optional.empty();
55	        }
56	
57	        if (userRegex.isPresent()) {
58	            if (userRegex.get().matcher(user).matches()) {
59	                return Optional.of(allow);
60	            }
61	        }
62	
63	        if (principalToUserSubstitution.isPresent()) {
64	            String userExtraction = matcher.replaceAll(principalToUserSubstitution.get());
65	            if (user.equals(userExtraction)) {
66	                return Optional.of(allow);
67	            }
68	        }
69	
70	        return Optional.empty();
71	    }
